content.content:
  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% if request.design_mode %}
  8→  {% comment %}
  9→    Theme Editor preview — render a static placeholder so no live API calls
 10→    are made during theme customization. The real widget loads on the storefront.
 11→  {% endcomment %}
 12→  <div style="
 13→    background:#ffffff;
 14→    border:1px solid #e1e3e5;
 15→    border-radius:8px;
 16→    padding:24px;
 17→    max-width:480px;
 18→    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 19→    box-sizing:border-box;
 20→    color:#202223;
 21→  ">
 22→    <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
 23→    <div style="display:flex;gap:8px;margin-bottom:12px;">
 24→      <input
 25→        type="text"
 26→        placeholder="Enter your zip code"
 27→        disabled
 28→        style="
 29→          flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
 30→          font-size:14px;background:#fafbfb;color:#202223;min-width:0;
 31→        "
 32→      >
 33→      <button
 34→        type="button"
 35→        disabled
 36→        style="
 37→          background:#008060;color:#fff;border:none;border-radius:8px;
 38→          padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
 39→          opacity:0.7;cursor:default;
 40→        "
 41→      >Check</button>
 42→    </div>
 43→    <div style="
 44→      background:#00806015;border-left:3px solid #008060;border-radius:8px;
 45→      padding:12px;font-size:14px;color:#008060;line-height:1.4;
 46→    ">
 47→      Great news! We deliver to your area.
 48→      <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
 49→    </div>
 50→    <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
 51→      Zip Code Checker — live widget loads on your storefront
 52→    </p>
 53→  </div>
 54→{% else %}
 55→
 56→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
 57→
 58→<div
 59→  id="zcc-widget-{{ block.id }}"
 60→  data-zcc-widget="true"
 61→  data-shop="{{ shop.permanent_domain }}"
 62→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 63→  data-block="{{ block.id }}"
 64→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 65→  {{ block.shopify_attributes }}
 66→></div>
 67→
 68→<script>
 69→(function () {
 70→  // Respect app embed toggle — if app embed block is not enabled in this theme,
 71→  // window.__zccAppEnabled will be undefined/falsy and we exit early.
 72→  if (!window.__zccAppEnabled) return;
 73→
 74→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 75→  var container = document.getElementById(ROOT_ID);
 76→  if (!container) return;
 77→
 78→  var SHOP = container.dataset.shop;
 79→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
 80→
 81→  // Try embedded config from metafield first (instant, no network needed)
 82→  var configStr = container.getAttribute("data-config");
 83→  if (configStr) {
 84→    try {
 85→      renderWidget(JSON.parse(configStr));
 86→      return;
 87→    } catch (e) {
 88→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
 89→    }
 90→  }
 91→
 92→  // Fallback: fetch config from API
 93→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
 94→    .then(function (r) {
 95→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
 96→      return r.json();
 97→    })
 98→    .then(function (cfg) { renderWidget(cfg); })
 99→    .catch(function (err) {
100→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
101→      renderWidget({});
102→    });
103→
104→  function renderWidget(cfg) {
105→    // Merge with defaults
106→    var D = {
107→      position: "inline",
108→      heading: "Check Delivery Availability",
109→      placeholder: "Enter your zip code",
110→      buttonText: "Check",
111→      successMessage: "Great news! We deliver to your area.",
112→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
113→      notFoundMessage: "This zip code was not found in our system.",
114→      primaryColor: "#008060",
115→      successColor: "#008060",
116→      errorColor: "#D72C0D",
117→      backgroundColor: "#FFFFFF",
118→      textColor: "#202223",
119→      borderRadius: "8",
120→      showEta: true,
121→      showZone: false,
122→      showWaitlistOnFailure: false,
123→      showCod: true,
124→      showReturnPolicy: true,
125→      showCutoffTime: true,
126→      showDeliveryDays: true,
127→      customCss: "",
128→      blockCartOnInvalid: false,
129→      showSocialProof: true,
130→    };
131→    Object.keys(D).forEach(function (k) {
132→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
133→    });
134→
135→    var rad = cfg.borderRadius + "px";
136→    var WID = "zcc-" + ROOT_ID;
137→
138→    if (cfg.position === "floating") {
139→      renderFloating(cfg, WID, rad);
140→    } else if (cfg.position === "popup") {
141→      renderPopup(cfg, WID, rad);
142→    } else {
143→      renderInline(cfg, WID, rad);
144→    }
145→  }
146→
147→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
148→  function injectCss(wid, cfg, rad) {
149→    var css =
150→      "#" + wid + "{" +
151→        "background:" + cfg.backgroundColor + " !important;" +
152→        "color:" + cfg.textColor + " !important;" +
153→        "border-radius:" + rad + " !important;" +
154→        "padding:24px !important;" +
155→        "border:1px solid #e1e3e5 !important;" +
156→        "max-width:480px;" +
157→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
158→        "box-sizing:border-box !important;" +
159→      "}" +
160→      "#" + wid + " *{box-sizing:border-box !important}" +
161→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
162→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
163→      "#" + wid + " .zcc-input{" +
164→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
165→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
166→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
167→      "}" +
168→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
169→      "#" + wid + " .zcc-btn{" +
170→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
171→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
172→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
173→      "}" +
174→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
175→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
176→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
177→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
178→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
179→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
180→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
181→      "#" + wid + " .zcc-wl-input{" +
182→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
183→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
184→      "}" +
185→      "#" + wid + " .zcc-wl-btn{" +
186→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
187→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
188→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
189→      "}" +
190→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
191→      "#" + wid + " .zcc-cutoff{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
192→      "#" + wid + " .zcc-days{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
193→      "#" + wid + " .zcc-cod{margin-top:4px !important;font-size:0.85em !important;font-weight:500 !important}" +
194→      "#" + wid + " .zcc-cod--available{color:#008060 !important}" +
195→      "#" + wid + " .zcc-cod--unavailable{color:#d72c0d !important}" +
196→      "#" + wid + " .zcc-return-policy{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
197→      "#" + wid + " .zcc-social-proof{display:block !important;font-size:0.82em !important;color:#6d7175 !important;margin-bottom:8px !important;font-style:italic !important}" +
198→      (cfg.customCss || "");
199→
200→    var styleEl = document.createElement("style");
201→    styleEl.textContent = css;
202→    document.head.appendChild(styleEl);
203→  }
204→
205→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
206→  function buildWidgetInner(wid, cfg, btnLabel) {
207→    return (
208→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
209→      '<div class="zcc-row">' +
210→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
211→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
212→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
213→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
214→      "</div>" +
215→      '<div id="' + wid + '-res"></div>'
216→    );
217→  }
218→
219→  function wireWidget(wid, cfg, API_BASE, SHOP) {
220→    var inp = document.getElementById(wid + "-inp");
221→    var btn = document.getElementById(wid + "-btn");
222→    var res = document.getElementById(wid + "-res");
223→    var btnLabel = cfg.buttonText;
224→    if (!inp || !btn || !res) return;
225→
226→    function normalizeZip(raw) {
227→      var z = raw.trim().toUpperCase();
228→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
229→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
230→      return z;
231→    }
232→
233→    function checkZip() {
234→      var zip = normalizeZip(inp.value);
235→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
236→      if (!zip) { inp.focus(); return; }
237→
238→      btn.disabled = true;
239→      btn.textContent = "\u2026";
240→      res.innerHTML = "";
241→
242→      fetch(
243→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
244→          "&zip=" + encodeURIComponent(zip)
245→      )
246→        .then(function (r) { return r.json(); })
247→        .then(function (data) {
248→          btn.disabled = false;
249→          btn.textContent = btnLabel;
250→
251→          // Store validation result for cart page
252→          try {
253→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
254→            sessionStorage.setItem('zcc:zip', zip);
255→            sessionStorage.setItem('zcc:shop', SHOP);
256→            // Fire custom event for other scripts to listen to
257→            window.dispatchEvent(new CustomEvent('zcc:validated', {
258→              detail: { valid: data.allowed, zip: zip }
259→            }));
260→          } catch(e) { /* sessionStorage may be unavailable */ }
261→
262→          if (data.allowed) {
263→            var html = '<div class="zcc-result ok">' + esc(data.message);
264→            if (cfg.showEta && data.eta) {
265→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
266→            }
267→            if (cfg.showZone && data.zone) {
268→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
269→            }
270→            if (cfg.showDeliveryDays && data.daysOfWeek) {
271→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
272→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
273→            }
274→            if (cfg.showCutoffTime && data.cutoffTime) {
275→              var parts = data.cutoffTime.split(':');
276→              var hr = parseInt(parts[0], 10);
277→              var min = parts[1] || '00';
278→              var ampm = hr >= 12 ? 'PM' : 'AM';
279→              var hr12 = hr % 12 || 12;
280→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
281→            }
282→            if (data.codAvailable === true) {
283→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
284→            } else if (data.codAvailable === false) {
285→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
286→            }
287→            if (data.returnPolicy) {
288→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
289→            }
290→            html += "</div>";
291→            res.innerHTML = html;
292→          } else {
293→            var html = '<div class="zcc-result fail">' + esc(data.message);
294→            if (cfg.showWaitlistOnFailure) {
295→              html +=
296→                '<div class="zcc-wl">' +
297→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
298→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
299→                "</div>";
300→            }
301→            html += "</div>";
302→            res.innerHTML = html;
303→
304→            if (cfg.showWaitlistOnFailure) {
305→              // Social proof count — insert before email input
306→              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
307→                var wlSection = document.getElementById(wid + "-wl-email");
308→                if (wlSection && wlSection.parentNode) {
309→                  var spEl = document.createElement('div');
310→                  spEl.className = 'zcc-social-proof';
311→                  var count = data.waitlistCount;
312→                  spEl.textContent = '\uD83D\uDE4B Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area';
313→                  wlSection.parentNode.insertBefore(spEl, wlSection);
314→                }
315→              }
316→
317→              var wBtn = document.getElementById(wid + "-wl-btn");
318→              if (wBtn) {
319→                wBtn.addEventListener("click", function () {
320→                  var emailEl = document.getElementById(wid + "-wl-email");
321→                  var email = emailEl ? emailEl.value.trim() : "";
322→                  if (!email) { if (emailEl) emailEl.focus(); return; }
323→                  joinWaitlist(zip, email, wBtn);
324→                });
325→              }
326→            }
327→          }
328→
329→          // Block/unblock Add to Cart based on result (if merchant enabled this)
330→          if (cfg.blockCartOnInvalid) {
331→            var ATC_SELECTORS = [
332→              'button[name="add"]',
333→              '.product-form__submit',
334→              '[data-product-add]',
335→              '.btn--add-to-cart',
336→              '.product-form button[type="submit"]',
337→              'button.shopify-payment-button__button',
338→              '.shopify-payment-button button',
339→              'button.product-form__cart-submit'
340→            ].join(',');
341→
342→            try {
343→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
344→              atcBtns.forEach(function(b) {
345→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
346→                  if (data.allowed) {
347→                    b.disabled = false;
348→                    b.style.opacity = '';
349→                    b.title = b.getAttribute('data-zcc-orig-title') || '';
350→                    b.removeAttribute('data-zcc-orig-title');
351→                    b.removeAttribute('data-zcc-blocked');
352→                  } else {
353→                    b.setAttribute('data-zcc-orig-title', b.title || '');
354→                    b.disabled = true;
355→                    b.style.opacity = '0.5';
356→                    b.title = 'Please enter a valid ZIP code to continue';
357→                    b.setAttribute('data-zcc-blocked', 'true');
358→                  }
359→                }
360→              });
361→            } catch(e) { /* DOM query may fail in some contexts */ }
362→          }
363→        })
364→        .catch(function () {
365→          btn.disabled = false;
366→          btn.textContent = btnLabel;
367→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
368→          try {
369→            sessionStorage.setItem('zcc:valid', 'false');
370→            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
371→          } catch(e) {}
372→        });
373→    }
374→
375→    btn.addEventListener("click", checkZip);
376→    inp.addEventListener("keydown", function (e) {
377→      if (e.key === "Enter") checkZip();
378→    });
379→
380→    // Re-enable buttons when customer clears the input
381→    inp.addEventListener('input', function() {
382→      if (!inp.value.trim() && cfg.blockCartOnInvalid) {
383→        try {
384→          var blocked = document.querySelectorAll('[data-zcc-blocked="true"]');
385→          blocked.forEach(function(b) {
386→            b.disabled = false;
387→            b.style.opacity = '';
388→            b.title = b.getAttribute('data-zcc-orig-title') || '';
389→            b.removeAttribute('data-zcc-blocked');
390→            b.removeAttribute('data-zcc-orig-title');
391→          });
392→          sessionStorage.removeItem('zcc:valid');
393→          sessionStorage.removeItem('zcc:zip');
394→        } catch(e) {}
395→      }
396→    });
397→  }
398→
399→  function joinWaitlist(zip, email, wBtn) {
400→    wBtn.disabled = true;
401→    wBtn.textContent = "Joining\u2026";
402→
403→    fetch(API_BASE + "/api/waitlist", {
404→      method: "POST",
405→      headers: { "Content-Type": "application/json" },
406→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
407→    })
408→      .then(function (r) { return r.json(); })
409→      .then(function (data) {
410→        var wlEl = wBtn.closest(".zcc-wl");
411→        if (data.success) {
412→          if (wlEl) wlEl.innerHTML =
413→            '<p style="font-size:13px;margin:6px 0 0">' +
414→            "\u2713 You\u2019ve been added to the waitlist!" +
415→            "</p>";
416→        } else {
417→          wBtn.disabled = false;
418→          wBtn.textContent = "Join Waitlist";
419→        }
420→      })
421→      .catch(function () {
422→        wBtn.disabled = false;
423→        wBtn.textContent = "Join Waitlist";
424→      });
425→  }
426→
427→  // ── Inline position ─────────────────────────────────────────────────────────
428→  function renderInline(cfg, WID, rad) {
429→    injectCss(WID, cfg, rad);
430→    container.id = WID;
431→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
432→    wireWidget(WID, cfg, API_BASE, SHOP);
433→  }
434→
435→  // ── Floating position ────────────────────────────────────────────────────────
436→  function renderFloating(cfg, WID, rad) {
437→    // The original container becomes invisible (just an anchor)
438→    container.style.display = "none";
439→
440→    injectCss(WID, cfg, rad);
441→
442→    // Additional styles for floating UI
443→    var floatCss =
444→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
445→      "#" + WID + "-panel{" +
446→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
447→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
448→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
449→      "}" +
450→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
451→      "#" + WID + "-panel .zcc-panel-header{" +
452→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
453→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
454→      "}" +
455→      "#" + WID + "-panel .zcc-panel-close{" +
456→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
457→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
458→      "}" +
459→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
460→      "#" + WID + "-trigger{" +
461→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
462→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
463→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
464→      "}" +
465→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
466→
467→    var floatStyle = document.createElement("style");
468→    floatStyle.textContent = floatCss;
469→    document.head.appendChild(floatStyle);
470→
471→    // Build floating shell
472→    var floatEl = document.createElement("div");
473→    floatEl.id = WID + "-float";
474→    floatEl.innerHTML =
475→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
476→        '<div class="zcc-panel-header">' +
477→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
478→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
479→        '</div>' +
480→        '<div id="' + WID + '" data-zcc-widget="true">' +
481→          buildWidgetInner(WID, cfg, cfg.buttonText) +
482→        '</div>' +
483→      '</div>' +
484→      '<button id="' + WID + '-trigger" type="button">' +
485→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
486→        esc(cfg.buttonText || "Check Delivery") +
487→      '</button>';
488→
489→    document.body.appendChild(floatEl);
490→
491→    // Wire toggle
492→    var trigger = document.getElementById(WID + "-trigger");
493→    var panel = document.getElementById(WID + "-panel");
494→    var closeBtn = document.getElementById(WID + "-close");
495→
496→    if (trigger && panel) {
497→      trigger.addEventListener("click", function () {
498→        panel.classList.toggle("zcc-hidden");
499→      });
500→    }
501→    if (closeBtn && panel) {
502→      closeBtn.addEventListener("click", function () {
503→        panel.classList.add("zcc-hidden");
504→      });
505→    }
506→    // Close on outside click
507→    document.addEventListener("click", function (e) {
508→      if (!floatEl.contains(e.target)) {
509→        if (panel) panel.classList.add("zcc-hidden");
510→      }
511→    });
512→
513→    wireWidget(WID, cfg, API_BASE, SHOP);
514→  }
515→
516→  // ── Popup position ───────────────────────────────────────────────────────────
517→  function renderPopup(cfg, WID, rad) {
518→    injectCss(WID, cfg, rad);
519→
520→    var popupCss =
521→      "#" + WID + "-overlay{" +
522→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
523→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
524→      "}" +
525→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
526→      "#" + WID + "-modal{" +
527→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
528→        "max-width:480px !important;width:100% !important;position:relative !important;" +
529→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
530→      "}" +
531→      "#" + WID + "-modal .zcc-modal-close{" +
532→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
533→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
534→      "}" +
535→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
536→      "#" + WID + "-popup-trigger{" +
537→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
538→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
539→        "cursor:pointer !important" +
540→      "}" +
541→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
542→
543→    var popupStyle = document.createElement("style");
544→    popupStyle.textContent = popupCss;
545→    document.head.appendChild(popupStyle);
546→
547→    // Trigger button renders in-place (inside the block)
548→    container.innerHTML =
549→      '<button id="' + WID + '-popup-trigger" type="button">' +
550→        esc(cfg.heading) +
551→      '</button>';
552→
553→    // Overlay + modal append to body
554→    var overlay = document.createElement("div");
555→    overlay.id = WID + "-overlay";
556→    overlay.innerHTML =
557→      '<div id="' + WID + '-modal">' +
558→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
559→        '<div id="' + WID + '" data-zcc-widget="true">' +
560→          buildWidgetInner(WID, cfg, cfg.buttonText) +
561→        '</div>' +
562→      '</div>';
563→    document.body.appendChild(overlay);
564→
565→    var trigger = document.getElementById(WID + "-popup-trigger");
566→    var closeBtn = document.getElementById(WID + "-modal-close");
567→    var modal = document.getElementById(WID + "-modal");
568→
569→    function openPopup() { overlay.classList.add("zcc-open"); }
570→    function closePopup() { overlay.classList.remove("zcc-open"); }
571→
572→    if (trigger) trigger.addEventListener("click", openPopup);
573→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
574→
575→    // Close on overlay backdrop click (not modal content)
576→    overlay.addEventListener("click", function (e) {
577→      if (e.target === overlay) closePopup();
578→    });
579→
580→    // Close on Escape key
581→    document.addEventListener("keydown", function (e) {
582→      if (e.key === "Escape") closePopup();
583→    });
584→
585→    wireWidget(WID, cfg, API_BASE, SHOP);
586→  }
587→
588→  function esc(str) {
589→    return String(str)
590→      .replace(/&/g, "&amp;")
591→      .replace(/</g, "&lt;")
592→      .replace(/>/g, "&gt;")
593→      .replace(/"/g, "&quot;");
594→  }
595→
596→  function escAttr(str) {
597→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
598→  }
599→})();
600→</script>
601→
602→{% endif %}
603→
604→{% schema %}
605→{
606→  "name": "Zip Code Checker",
607→  "target": "section",
608→  "settings": []
609→}
610→{% endschema %}
